std::string convertMarkdownToHTML(const std::string& markdown) {
    // Define the rules for conversion from markdown to HTML
    std::string html = "";
    std::string current_line = "";
    bool is_header = false;
    bool is_bold = false;
    bool is_italic = false;
    bool is_link = false;
    bool is_image = false;
    std::string link_url = "";
    std::string link_text = "";
    std::string image_url = "";
    std::string image_alt_text = "";

    for (char c : markdown) {
        if (is_header) {
            if (c == '#') {
                int level = std::count(current_line.rbegin(), current_line.rend(), '#');
                html += "<h" + std::to_string(level) + ">" + link_text + "</h" + std::to_string(level) + ">";
                is_header = false;
            } else {
                current_line += c;
            }
        } else if (is_bold) {
            if (c == '*') {
                html += "<strong>" + link_text + "</strong>";
                is_bold = false;
            } else {
                current_line += c;
            }
        } else if (is_italic) {
            if (c == '*') {
                html += "<em>" + link_text + "</em>";
                is_italic = false;
            } else {
                current_line += c;
            }
        } else if (is_link) {
            if (c == ']') {
                link_text = current_line;
                is_link = false;
                current_line = "";
            } else {
                current_line += c;
            }
        } else if (is_image) {
            if (c == ']') {
                image_alt_text = current_line;
                is_image = false;
                current_line = "";
            } else {
                current_line += c;
            }
        } else {
            switch (c) {
                case '#':
                    is_header = true;
                    break;
                case '*':
                    is_bold = !is_bold;
                    break;
                case '_':
                    is_italic = !is_italic;
                    break;
                case '[':
                    is_link = true;
                    break;
                case '(':
                    is_image = true;
                    break;
                default:
                    current_line += c;
            }
        }
    }

    if (!is_header && !is_bold && !is_italic && !is_link && !is_image) {
        html += link_text;
    }

    return html;
}

int main() {
    std::string markdown = "# Hello, world!\n\nThis is some *bold* and _italic_ text.";
    std::string html = convertMarkdownToHTML(markdown);
    std::cout << html << std::endl;
    return 0;
}
